本、小说文本或酒馆消息...&#10;提取规则：自动提取所有以“{爱蜜莉雅}”开头的段落台词，也可点击上方“从当前酒馆消息导入”。\"\n      ></textarea>\n    </div>\n\n    <div class=\"card-footer\">\n      <p class=\"rule-hint\">\n        <Pin :size=\"14\" class=\"hint-icon\" />\n        <span>提取规则：支持处理以 <strong>{爱蜜莉雅}</strong> 或 <strong>&lt;tts&gt;</strong> 标记的角色台词。</span>\n      </p>\n      <div class=\"footer-right\">\n        <span class=\"char-count\">{{ rawText.length }} 字</span>\n        <button class=\"primary-button\" :disabled=\"!rawText.trim()\" @click=\"handleExtract\">\n          <ScanText :size=\"16\" /> 提取对白\n        </button>\n      </div>\n    </div>\n  </section>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, onMounted } from 'vue'\nimport { BookOpen, Eraser, MessageSquareText, Pin, ScanText } from 'lucide-vue-next'\nimport { extractDialogues, extractXmlTagContent } from '../services/dialogueExtractor'\nimport type { DialogueItem } from '../types'\nimport sampleInput from '../data/input.txt?raw'\nimport { addLog } from '../services/logger'\n\nconst props = defineProps<{\n  xmlTag?: string\n}>()\n\nconst emit = defineEmits<{\n  (e: 'extracted', items: DialogueItem[], fullText: string): void\n}>()\n\nconst rawText = ref('')\n\nonMounted(() => {\n  rawText.value = sampleInput\n})\n\nfunction loadSampleText() {\n  rawText.value = sampleInput\n  addLog('info', 'EXTRACT', '已载入示例轻小说剧本文本')\n}\n\nfunction loadFromTavernChat() {\n  try {\n    if (typeof getChatMessages === 'function') {\n      const messages = getChatMessages()\n      if (messages && messages.length > 0) {\n        // 查找最新的非用户消息（AI角色的消息）\n        const aiMsgs = messages.filter((m: any) => !m.is_user && m.message)\n        const lastMsg = aiMsgs.length > 0 ? aiMsgs[aiMsgs.length - 1] : messages[messages.length - 1]\n        if (lastMsg && lastMsg.message) {\n          const content = String(lastMsg.message)\n          // 如果有 xmlTag，优先提取标签内\n          const tag = props.xmlTag || 'tts'\n          const extractedTag = extractXmlTagContent(content, tag)\n          rawText.value = extractedTag || content\n          addLog('success', 'EXTRACT', `成功从酒馆最新消息导入文本 (${rawText.value.length} 字符)`)\n          handleExtract()\n          return\n        }\n      }\n    }\n    alert('未能从当前酒馆对话中读取到消息，请确认当前已打开聊天。')\n  } catch (err: any) {\n    alert(`读取酒馆消息失败: ${err.message}`)\n  }\n}\n\nfunction handleExtract() {\n  const list = extractDialogues(rawText.value)\n  if (list.length === 0) {\n    alert('未在文本中找到任何以“{爱蜜莉雅}”开头的段落或台词，请检查输入格式。')\n    return\n  }\n  emit('extracted', list, rawText.value)\n}\n</script>\n\n<style scoped>\n.card-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 14px 20px;\n  border-bottom: 1px solid var(--rule);\n  flex-wrap: wrap;\n  gap: 12px;\n}\n\n.header-left {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.step-badge {\n  width: 32px;\n  height: 32px;\n  display: grid;\n  place-items: center;\n  border: 1px solid var(--gold);\n  background: rgba(184, 134, 11, 0.1);\n  color: var(--gold);\n  font-family: var(--font-mono);\n  font-size: 0.85rem;\n  font-weight: 700;\n  border-radius: 6px;\n}\n\n.card-title {\n  margin: 0;\n  font-size: 1.1rem;\n  font-weight: 600;\n  color: var(--ink);\n  font-family: var(--font-display);\n}\n\n.header-actions {\n  display: flex;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n.card-body {\n  padding: 16px 20px;\n}\n\n.text-input {\n  width: 100%;\n  min-height: 140px;\n  border: 1px solid var(--rule);\n  background: var(--surface);\n  border-radius: 8px;\n  padding: 12px 14px;\n  font-family: var(--font-mono);\n  font-size: 0.85rem;\n  line-height: 1.7;\n  color: var(--ink);\n  resize: vertical;\n  outline: none;\n  box-sizing: border-box;\n  transition: all 150ms ease;\n}\n\n.text-input:focus {\n  border-color: var(--gold);\n  background: var(--paper);\n  box-shadow: 0 0 0 3px var(--focus-ring);\n}\n\n.card-footer {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 12px 20px;\n  border-top: 1px solid var(--rule);\n  background: rgba(245, 243, 240, 0.6);\n  flex-wrap: wrap;\n  gap: 12px;\n}\n\n.rule-hint {\n  margin: 0;\n  font-size: 0.78rem;\n  color: var(--muted-ink);\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.hint-icon {\n  color: var(--gold);\n  flex-shrink: 0;\n}\n\n.footer-right {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n}\n\n.char-count {\n  font-family: var(--font-mono);\n  font-size: 0.75rem;\n  color: var(--muted-ink);\n}\n</style>\n"],"sourceRoot":""}]);
