     <label>默认语速倍率 (Speed)：{{ form.speed }}x</label>\n            <input\n              v-model.number=\"form.speed\"\n              type=\"range\"\n              min=\"0.5\"\n              max=\"2.0\"\n              step=\"0.05\"\n              class=\"range-control\"\n            />\n          </div>\n\n          <div class=\"form-group\">\n            <label>噪声强度 (Noise Scale)：{{ form.noise_scale }}</label>\n            <input\n              v-model.number=\"form.noise_scale\"\n              type=\"range\"\n              min=\"0.1\"\n              max=\"1.0\"\n              step=\"0.05\"\n              class=\"range-control\"\n            />\n          </div>\n\n          <div class=\"form-group\">\n            <label>采样温度 (Temperature)：{{ form.temperature }}</label>\n            <input\n              v-model.number=\"form.temperature\"\n              type=\"range\"\n              min=\"0.2\"\n              max=\"1.5\"\n              step=\"0.05\"\n              class=\"range-control\"\n            />\n          </div>\n\n          <div class=\"form-group\">\n            <label>重复惩罚 (Repetition Penalty)：{{ form.repetition_penalty }}</label>\n            <input\n              v-model.number=\"form.repetition_penalty\"\n              type=\"range\"\n              min=\"1.0\"\n              max=\"2.0\"\n              step=\"0.05\"\n              class=\"range-control\"\n            />\n          </div>\n\n          <div class=\"form-group\">\n            <label>Top K：{{ form.top_k }}</label>\n            <input\n              v-model.number=\"form.top_k\"\n              type=\"range\"\n              min=\"1\"\n              max=\"50\"\n              step=\"1\"\n              class=\"range-control\"\n            />\n          </div>\n\n          <div class=\"form-group\">\n            <label>Top P：{{ form.top_p }}</label>\n            <input\n              v-model.number=\"form.top_p\"\n              type=\"range\"\n              min=\"0.1\"\n              max=\"1.0\"\n              step=\"0.05\"\n              class=\"range-control\"\n            />\n          </div>\n        </div>\n\n        <div class=\"switch-row\">\n          <label class=\"switch-label\">\n            <input v-model=\"form.return_subtitles\" type=\"checkbox\" />\n            <span>返回时间轴字幕 (return_subtitles)</span>\n          </label>\n        </div>\n\n        <details class=\"advanced-section\">\n          <summary>高级（兼容旧版参数）</summary>\n          <div class=\"switch-row\">\n            <label class=\"switch-label\">\n              <input v-model=\"form.is_cut_text\" type=\"checkbox\" />\n              <span>按标点切分长句 (is_cut_text)</span>\n            </label>\n          </div>\n          <div class=\"cut-params-row\">\n            <div class=\"form-group half\">\n              <label>切分最小长度 (cut_minlen)：</label>\n              <input v-model.number=\"form.cut_minlen\" type=\"number\" min=\"1\" max=\"100\" class=\"input-control\" />\n            </div>\n            <div class=\"form-group half\">\n              <label>切分静音时长 (cut_mute 秒)：</label>\n              <input v-model.number=\"form.cut_mute\" type=\"number\" step=\"0.05\" min=\"0\" max=\"2\" class=\"input-control\" />\n            </div>\n          </div>\n          <small>勾选\"切分方式\"非 cut0 时，后端会忽略这些字段。</small>\n        </details>\n\n        <div\n          v-if=\"testMessage\"\n          class=\"test-message\"\n          :class=\"{ error: testStatus === 'error', success: testStatus === 'success' }\"\n        >\n          {{ testMessage }}\n        </div>\n      </div>\n\n      <div class=\"modal-footer\">\n        <button class=\"tool-button\" :disabled=\"testing\" @click=\"testTTS\">\n          {{ testing ? '测试中...' : '🔌 检查服务状态' }}\n        </button>\n        <div class=\"footer-actions\">\n          <button class=\"tool-button\" @click=\"$emit('close')\">取消</button>\n          <button class=\"primary-button\" @click=\"save\">保存设置</button>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, reactive, watch } from 'vue'\nimport type { TTSConfig } from '../types'\nimport { checkTTSHealth } from '../services/tts'\nimport { CUT_METHOD_OPTIONS } from '../config'\n\nconst props = defineProps<{\n  visible: boolean\n  config: TTSConfig\n}>()\n\nconst emit = defineEmits<{\n  (e: 'close'): void\n  (e: 'save', config: TTSConfig): void\n}>()\n\nconst form = reactive<TTSConfig>({ ...props.config })\n\nwatch(() => props.config, (newVal) => {\n  Object.assign(form, newVal)\n}, { deep: true })\n\nconst testing = ref(false)\nconst testStatus = ref<'idle' | 'success' | 'error'>('idle')\nconst testMessage = ref('')\n\nconst cutMethodOptions = CUT_METHOD_OPTIONS\n\nasync function testTTS() {\n  testing.value = true\n  testStatus.value = 'idle'\n  testMessage.value = '正在向 GSV-TTS 服务发起连通性检查...'\n\n  try {\n    const health = await checkTTSHealth(form.baseUrl)\n    if (health.ok) {\n      testStatus.value = 'success'\n      testMessage.value = `✅ ${health.message}`\n    } else {\n      testStatus.value = 'error'\n      testMessage.value = `❌ ${health.message}`\n    }\n  } catch (err: any) {\n    testStatus.value = 'error'\n    testMessage.value = `❌ 连接异常: ${err.message}`\n  } finally {\n    testing.value = false\n  }\n}\n\nfunction save() {\n  // 联动：选 cut0 时 is_cut_text 自动 false\n  form.is_cut_text = form.text_split_method !== 'cut0'\n  emit('save', { ...form })\n  emit('close')\n}\n</script>\n\n<style scoped>\n.form-group {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.form-group label {\n  font-size: 0.82rem;\n  font-weight: 600;\n  color: var(--ink);\n}\n\n.form-group small {\n  font-size: 0.72rem;\n  color: var(--muted-ink);\n}\n\n.param-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 14px 18px;\n}\n\n.range-control {\n  width: 100%;\n  accent-color: var(--gold);\n  cursor: pointer;\n}\n\n.switch-row {\n  display: flex;\n  gap: 20px;\n  flex-wrap: wrap;\n  padding: 6px 0;\n}\n\n.switch-label {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 0.82rem;\n  cursor: pointer;\n  user-select: none;\n}\n\n.cut-params-row {\n  display: flex;\n  gap: 16px;\n}\n\n.form-group.half {\n  flex: 1;\n}\n\n.advanced-section {\n  border: 1px solid var(--border, #ccc);\n  border-radius: 6px;\n  padding: 10px 14px;\n  background: var(--bg-soft, rgba(0, 0, 0, 0.02));\n}\n\n.advanced-section summary {\n  cursor: pointer;\n  font-size: 0.82rem;\n  font-weight: 600;\n  color: var(--ink);\n  user-select: none;\n}\n\n.advanced-section[open] summary {\n  margin-bottom: 12px;\n}\n\n.test-message {\n  font-size: 0.78rem;\n  padding: 8px 12px;\n  border-radius: 6px;\n  font-family: var(--font-mono);\n}\n\n.test-message.success {\n  background: rgba(40, 112, 77, 0.1);\n  color: var(--success);\n  border: 1px solid var(--success);\n}\n\n.test-message.error {\n  background: rgba(168, 59, 50, 0.1);\n  color: var(--danger);\n  border: 1px solid var(--danger);\n}\n</style>\n"],"sourceRoot":""}]);
