"tool-button\" :disabled=\"loading\" @click=\"loadTasks\">🔄 刷新</button>\n          <button class=\"close-btn\" @click=\"$emit('close')\">✕</button>\n        </div>\n      </div>\n\n      <div class=\"modal-body\">\n        <div v-if=\"loading\" class=\"empty-state\">正在加载历史任务...</div>\n        <div v-else-if=\"tasks.length === 0\" class=\"empty-state\">暂无对白合成历史记录</div>\n        <div v-else class=\"history-layout\">\n          <div class=\"task-list\">\n            <button\n              v-for=\"task in tasks\"\n              :key=\"task.task_id\"\n              class=\"task-row\"\n              :class=\"{ active: selected?.task_id === task.task_id }\"\n              @click=\"selectTask(task.task_id)\"\n            >\n              <div class=\"task-row-top\">\n                <strong>{{ formatDate(task.created_at) }}</strong>\n                <span class=\"status-pill\" :class=\"task.status\">{{ formatStatus(task.status) }}</span>\n              </div>\n              <div class=\"task-row-meta\">\n                {{ task.total_items }} 条对白 · LLM {{ formatMs(task.llm_wait_ms) }} · TTS {{ formatMs(task.tts_inference_ms) }}\n              </div>\n            </button>\n          </div>\n\n          <div v-if=\"selected\" class=\"task-detail\">\n            <div class=\"metrics-grid\">\n              <div class=\"metric-card\">\n                <span>LLM 耗时</span>\n                <strong>{{ formatMs(selected.llm_wait_ms) }}</strong>\n              </div>\n              <div class=\"metric-card\">\n                <span>TTS 请求</span>\n                <strong>{{ formatMs(selected.tts_request_ms) }}</strong>\n              </div>\n              <div class=\"metric-card\">\n                <span>TTS 推理</span>\n                <strong>{{ formatMs(selected.tts_inference_ms) }}</strong>\n              </div>\n              <div class=\"metric-card\">\n                <span>音频拼接</span>\n                <strong>{{ formatMs(selected.merge_ms) }}</strong>\n              </div>\n              <div class=\"metric-card\">\n                <span>总耗时</span>\n                <strong>{{ formatMs(selected.total_ms) }}</strong>\n              </div>\n            </div>\n\n            <div v-if=\"selected.error_message\" class=\"error-box\">\n              {{ selected.error_message }}\n            </div>\n\n            <div class=\"items-table-wrap\">\n              <table class=\"items-table\">\n                <thead>\n                  <tr>\n                    <th style=\"width: 36px\">#</th>\n                    <th style=\"width: 180px\">对白原文</th>\n                    <th style=\"width: 220px\">日语台词</th>\n                    <th style=\"width: 90px\">情绪/语速</th>\n                    <th style=\"width: 140px\">音频</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr v-for=\"(item, index) in selected.items || []\" :key=\"`${selected.task_id}-${index}`\">\n                    <td class=\"text-center font-mono\">{{ item.source_index || index + 1 }}</td>\n                    <td>{{ item.original_text || '-' }}</td>\n                    <td>{{ item.text || '-' }}</td>\n                    <td>{{ item.inferred_emotion || '-' }} / {{ item.speed || '-' }}</td>\n                    <td>\n                      <audio v-if=\"item.audio_url\" controls :src=\"item.audio_url\" class=\"mini-audio\"></audio>\n                      <span v-else class=\"text-muted\">{{ item.audio_status || '-' }}</span>\n                    </td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"modal-footer\">\n        <span class=\"footer-tip\">历史记录基于后端任务接口与本地会话自动记录。</span>\n        <button class=\"tool-button\" @click=\"$emit('close')\">关闭</button>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, watch } from 'vue'\nimport type { StudioTask, TTSConfig } from '../types'\nimport { getStudioTask, listStudioTasks } from '../services/studioTasks'\n\nconst props = defineProps<{\n  visible: boolean\n  config: TTSConfig\n}>()\n\ndefineEmits<{\n  (e: 'close'): void\n}>()\n\nconst tasks = ref<StudioTask[]>([])\nconst selected = ref<StudioTask | null>(null)\nconst loading = ref(false)\n\nwatch(() => props.visible, (visible) => {\n  if (visible) {\n    loadTasks()\n  }\n})\n\nasync function loadTasks() {\n  loading.value = true\n  try {\n    const res = await listStudioTasks(props.config, 30, 0)\n    tasks.value = res.items || []\n    if (tasks.value.length > 0) {\n      selectTask(tasks.value[0].task_id)\n    } else {\n      selected.value = null\n    }\n  } catch (err) {\n    tasks.value = []\n    selected.value = null\n  } finally {\n    loading.value = false\n  }\n}\n\nasync function selectTask(taskId: string) {\n  try {\n    const task = await getStudioTask(props.config, taskId)\n    selected.value = task\n  } catch (err) {\n    selected.value = tasks.value.find(t => t.task_id === taskId) || null\n  }\n}\n\nfunction formatDate(iso: string) {\n  if (!iso) return '-'\n  try {\n    const d = new Date(iso)\n    return `${d.getMonth() + 1}/${d.getDate()} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`\n  } catch {\n    return iso\n  }\n}\n\nfunction formatStatus(status: string) {\n  switch (status) {\n    case 'succeeded': return '成功'\n    case 'failed': return '失败'\n    case 'running': return '执行中'\n    default: return status || '未知'\n  }\n}\n\nfunction formatMs(val?: number | null) {\n  if (val === null || val === undefined) return '-'\n  if (val < 1000) return `${Math.round(val)}ms`\n  return `${(val / 1000).toFixed(2)}s`\n}\n</script>\n\n<style scoped>\n.history-modal {\n  max-width: 1080px;\n  width: 95%;\n  height: 85vh;\n}\n\n.header-left {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.count-tag {\n  font-family: var(--font-mono);\n  font-size: 0.72rem;\n  background: var(--surface);\n  border: 1px solid var(--rule);\n  padding: 2px 8px;\n  border-radius: 9999px;\n  color: var(--muted-ink);\n}\n\n.header-actions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.history-layout {\n  display: grid;\n  grid-template-columns: 280px 1fr;\n  gap: 16px;\n  height: 100%;\n  min-height: 420px;\n}\n\n.task-list {\n  border: 1px solid var(--rule);\n  border-radius: 8px;\n  background: var(--surface);\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n}\n\n.task-row {\n  padding: 10px 12px;\n  border: none;\n  border-bottom: 1px solid var(--rule);\n  background: transparent;\n  text-align: left;\n  cursor: pointer;\n  transition: all 120ms ease;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.task-row:hover {\n  background: rgba(184, 134, 11, 0.06);\n}\n\n.task-row.active {\n  background: var(--paper);\n  border-left: 3px solid var(--gold);\n}\n\n.task-row-top {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.task-row-meta {\n  font-family: var(--font-mono);\n  font-size: 0.7rem;\n  color: var(--muted-ink);\n}\n\n.task-detail {\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n  overflow: hidden;\n}\n\n.metrics-grid {\n  display: grid;\n  grid-template-columns: repeat(5, 1fr);\n  gap: 10px;\n}\n\n.metric-card {\n  border: 1px solid var(--rule);\n  background: var(--surface);\n  border-radius: 8px;\n  padding: 8px 10px;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.metric-card span {\n  font-size: 0.7rem;\n  color: var(--muted-ink);\n}\n\n.metric-card strong {\n  font-family: var(--font-mono);\n  font-size: 0.95rem;\n  color: var(--ink);\n}\n\n.items-table-wrap {\n  flex: 1;\n  overflow-y: auto;\n  border: 1px solid var(--rule);\n  border-radius: 8px;\n}\n\n.items-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 0.8rem;\n}\n\n.items-table th {\n  position: sticky;\n  top: 0;\n  background: var(--surface);\n  padding: 8px 10px;\n  border-bottom: 1px solid var(--rule);\n  font-family: var(--font-mono);\n  font-size: 0.72rem;\n  color: var(--muted-ink);\n  text-align: left;\n}\n\n.items-table td {\n  padding: 8px 10px;\n  border-bottom: 1px solid var(--rule);\n  vertical-align: middle;\n}\n\n.mini-audio {\n  height: 28px;\n  max-width: 150px;\n}\n\n.status-pill {\n  font-family: var(--font-mono);\n  font-size: 0.65rem;\n  padding: 2px 6px;\n  border-radius: 4px;\n  border: 1px solid currentColor;\n}\n.status-pill.succeeded { color: var(--success); }\n.status-pill.failed { color: var(--danger); }\n.status-pill.running { color: var(--gold); }\n\n.error-box {\n  padding: 8px 12px;\n  border-radius: 6px;\n  border: 1px solid var(--danger);\n  background: rgba(168, 59, 50, 0.08);\n  color: var(--danger);\n  font-size: 0.78rem;\n}\n\n.footer-tip {\n  font-size: 0.75rem;\n  color: var(--muted-ink);\n}\n\n.empty-state {\n  display: grid;\n  place-items: center;\n  padding: 40px;\n  color: var(--muted-ink);\n}\n\n.text-muted { color: var(--muted-ink); }\n.text-center { text-align: center; }\n.font-mono { font-family: var(--font-mono); }\n</style>\n"],"sourceRoot":""}]);
